CREATE TABLE IF NOT EXISTS `controlstore_sena`.`rol_permiso` (
  `id_rol` TINYINT NOT NULL COMMENT 'FK: rol',
  `id_permiso` INT NOT NULL COMMENT 'FK: permiso concedido',
  PRIMARY KEY (`id_rol`, `id_permiso`),
  INDEX `fk_rol_permiso_permiso` (`id_permiso` ASC) VISIBLE,
  CONSTRAINT `fk_rol_permiso_permiso`
    FOREIGN KEY (`id_permiso`)
    REFERENCES `controlstore_sena`.`permisos` (`id_permiso`)
    ON DELETE CASCADE
    ON UPDATE CASCADE,
  CONSTRAINT `fk_rol_permiso_rol`
    FOREIGN KEY (`id_rol`)
    REFERENCES `controlstore_sena`.`roles` (`id_rol`)
    ON DELETE CASCADE
    ON UPDATE CASCADE)
ENGINE = InnoDB
DEFAULT CHARACTER SET = utf8mb4
COLLATE = utf8mb4_spanish_ci
COMMENT = 'Qué permisos tiene cada rol (relación N:M)';


